template <typename T>
class OStream_Iter_ZeroOverhead {
    std::ostream* os_ptr;
    const char* delimiter; // Minimal memory state (2 pointers)

public:
    OStream_Iter_ZeroOverhead(std::ostream& s, const char* d="")
        : os_ptr(&s), delimiter(d) {}

    // No-Op operations (Abstraction layer)
    // Compiler optimizes these away via inlining.
    OStream_Iter_ZeroOverhead& operator*() { return *this; }
    OStream_Iter_ZeroOverhead& operator++() { return *this; }
    void operator++(int) {}

    // Assignment performs the work: output + delimiter
    void operator=(const T& value) {
        *os_ptr << value << delimiter;
    }
    // Performance: Cost equals direct stream write.
};
